"Ацтекская":"Azteca",
"Америка — от Аляски до Огненной Земли":"América, de Alaska a Tierra del Fuego",
"Оберег":"Talismán",
"Узелок с заговорённой травой. Бросай в духа, чтобы поймать.":"Un hatillo de hierbas encantadas. Lánzalo a un espíritu para atraparlo.",
"Серебряный оберег":"Talismán plateado",
"Серебро держит духов крепче. Шанс поимки ×1,5.":"La plata sujeta mejor a los espíritus. Probabilidad de captura ×1,5.",
"Золотой оберег":"Talismán dorado",
"Лучший оберег Ордена. Шанс поимки ×2.":"El mejor talismán de la Orden. Probabilidad de captura ×2.",
"Духи обожают мёд. Успокаивает духа: шанс поимки ×1,5 на один бросок.":"A los espíritus les encanta la miel. Calma al espíritu: probabilidad de captura ×1,5 en un lanzamiento.",
"Подорожник":"Llantén",
"Лист к ране — и полегчало. Возвращает духу четверть здоровья.":"Una hoja sobre la herida y ya está mejor. Devuelve al espíritu una cuarta parte de su salud.",
"Целебный отвар":"Infusión curativa",
"Травы Велеса, сваренные в воде из источника. Возвращает духу 60% здоровья.":"Hierbas de Veles hervidas en agua de manantial. Devuelve al espíritu el 60% de su salud.",
"Мёртвая вода":"Myortvaya Voda",
"Редкая сказочная вода, что сращивает самые тяжкие раны. Дух без сил поднимется на 4 часа раньше. Живых не лечит.":"Una rara agua de cuento que cierra las heridas más graves. Un espíritu debilitado se recupera 4 horas antes. No cura a los que siguen en pie.",
"Живая вода":"Zhivaya Voda",
"Возвращает духу половину здоровья, а в разломе — лечит прямо в бою. Духа без сил не поднимет.":"Devuelve al espíritu la mitad de su salud, y en una grieta cura en pleno combate. No reanima a un espíritu debilitado.",
"Ладан":"Incienso",
"Дымок приманивает духов: 30 минут их вокруг вдвое больше.":"Su humo atrae a los espíritus: durante 30 minutos habrá el doble a tu alrededor.",
"Дальний пропуск":"Pase lejano",
"Грамота Ордена: закрыть Разлом до 5 км от тебя, не подходя к нему. Один Орден дарит каждый день.":"Un documento de la Orden: cierra una grieta a hasta 5 km de ti sin acercarte. La Orden regala uno cada día.",
"Кольцо Ордена с воронкой дорог: шагни в любое место Атласа мира сразу, не дожидаясь перезарядки. Одни Врата дарят на седьмой день серии.":"Un anillo de la Orden con un remolino de caminos: ve a cualquier lugar del Atlas del mundo al instante, sin esperar la recarga. Regalan unas el séptimo día de la racha.",
"Настой опыта":"Tónico de PX",
"Медовый настой на травах Велеса: сутки опыта на четверть больше.":"Tónico de miel con hierbas de Veles: un día con un cuarto más de PX.",
"Подарок":"Regalo",
"Узелок для друга: обереги, мёд, иногда кокон. Отправляется в «Меню → Друзья», раз в день каждому.":"Un hatillo para un amigo: talismanes, miel y a veces un capullo. Se envía en «Menú → Amigos», una vez al día a cada uno.",
