"Покров":"Pokrov",
"Первые туманы и иней: духи Ветра и Воды встречаются чаще, Листопадница — повсюду, в источниках больше добычи.":"Primeras nieblas y escarchas: más espíritus de Viento y Agua, Listopadnitsa por todas partes y más botín en las fuentes.",
"Велесова ночь":"La noche de Veles",
"Граница миров тоньше всего: духи Тени втрое чаще, в великих разломах ждёт Кощей, сияющие Тени вдвое чаще.":"La frontera entre los mundos está en su punto más fino: espíritus de Sombra el triple de a menudo, Koschei espera en las Grandes grietas y las Sombras brillantes aparecen el doble.",
