"Поражение":"Derrota",
"«Приходи, когда окрепнешь», — говорит {0}. Попробуй другую команду: смотри на стихии хранителя и береги щиты для его приёмов.":"«Vuelve cuando seas más fuerte», dice {0}. Prueba con otro equipo: fíjate en los elementos del guardián y guarda los escudos para sus técnicas.",
"Хорошая тренировка! Награда за поединок с {0} сегодня уже получена.":"¡Buen entrenamiento! La recompensa por el duelo con {0} ya la recibiste hoy.",
"{0} жмёт тебе руку: «Честный бой!» Дружба крепнет.":"{0} te estrecha la mano: «¡Combate limpio!» La amistad se fortalece.",
"<b>+1 ★</b> дружбы":"<b>+1 ★</b> de amistad",
"Духи {0} оказались сильнее. Подбери команду против их стихий и попробуй снова — поединки с другом не ограничены.":"Los espíritus de {0} fueron más fuertes. Elige un equipo contra sus elementos y vuelve a intentarlo: los duelos con amigos no tienen límite.",
"Источник освобождён!":"¡Fuente liberada!",
