"Друг у разлома нажал «Позвать друзей» и прислал код из 5 символов? Введи его — и в бой вместе, где бы ты ни был.":"¿Un amigo en una grieta pulsó «Invitar amigos» y te envió un código de 5 caracteres? Introdúcelo y a luchar juntos, estés donde estés.",
