"В Лиге дерутся живые Ловчие: победа над сильным соперником даёт больше рейтинга, чем над слабым.":"En la Liga luchan Cazadores reales: vencer a un rival fuerte da más puntuación que a uno débil.",
"Разломы открываются у Святилищ каждый час: собери команду из трёх духов.":"Las grietas se abren junto a los Santuarios cada hora: forma un equipo de tres espíritus.",
"Сияющие духи редки — их выдают искры вокруг.":"Los espíritus brillantes son raros: los delatan las chispas a su alrededor.",
"Коконы греются шагами: одновременно можно греть три.":"Los capullos se incuban con tus pasos: puedes incubar tres a la vez.",
"Ходи джойстиком: лёгкий наклон — шаг, до упора — бег. Километры для коконов считаются так же.":"Muévete con el joystick: una ligera inclinación es caminar y a fondo, correr. Los kilómetros cuentan igual para los capullos.",
"Атлас мира переносит в любой уголок Земли раз в полчаса, а Врата Перепутицы — сразу.":"El Atlas del mundo te lleva a cualquier rincón de la Tierra cada media hora; las Puertas de la Gran Maraña, al instante.",
"Задания дня обновляются в полночь, а за все три ждёт Сундук дня.":"Las misiones del día se renuevan a medianoche, y si completas las tres te espera el Cofre del día.",
