" На этой неделе {0}.":" Esta semana, {0}.",
"Цель растёт с числом участников. Награду ступени получает каждый, кто внёс нужное число очков.":"La meta crece con el número de participantes. La recompensa de cada peldaño la recibe todo el que aporte los puntos necesarios.",
