"Предел уровня духа +{0} за осколки Алатыря":"Límite de nivel del espíritu +{0} con fragmentos de Alatyr",
"Вершина пути":"La cima del camino",
"Максимальный уровень Ловчего":"Nivel máximo de Cazador",
"Сегодня получено {0} опыта — полностью до {1}":"Hoy llevas {0} PX: completos hasta {1}",
"Сегодня получено {0} опыта — дальше вполовину до {1}":"Hoy llevas {0} PX: ahora a la mitad hasta {1}",
"Сегодня получено {0} опыта — дальше на четверть":"Hoy llevas {0} PX: ahora a un cuarto",
"Опыт отдыха: следующие {0} опыта — вдвое":"PX de descanso: los próximos {0} PX, dobles",
"За день опыт идёт полностью до {0}, дальше до {1} — вполовину, сверх — на четверть. Обучение и знаки Ордена дают опыт всегда полностью. За каждый день без игры копится опыт отдыха ({2}, не больше чем за {3} {4}): пока он есть, опыт вдвое.":"Cada día los PX cuentan completos hasta {0}; después, hasta {1}, a la mitad, y por encima, a un cuarto. El tutorial y las insignias de la Orden siempre dan PX completos. Por cada día sin jugar se acumulan PX de descanso ({2}, como máximo por {3} {4}): mientras los tengas, ganas PX dobles.",
"Звание «{0}»":"Título «{0}»",
"Ты здесь":"Estás aquí",
"Ты прошёл весь путь!":"¡Has recorrido todo el camino!",
"До {0} уровня — {1} опыта":"Hasta el nivel {0}: {1} PX",
"дальше: {0} на {1}":"después: {0} en el nivel {1}",
"Опыт дают поимки, источники, разломы, святилища и задания. С уровнем растут и твои духи: их можно усиливать до уровня Ловчего +5.":"La experiencia se gana con capturas, fuentes, grietas, Santuarios y misiones. Con tu nivel crecen también tus espíritus: puedes potenciarlos hasta el nivel del Cazador +5.",
"С {0} уровня духов можно пробуждать: каждая звезда поднимает предел уровня духа ещё на {1}, до {2}.":"Desde el nivel {0} puedes despertar espíritus: cada estrella sube el límite de nivel del espíritu {1} más, hasta {2}.",
"Ищу настоящие места вокруг — Источники и Святилища появятся через несколько секунд":"Buscando lugares reales a tu alrededor: las fuentes y los Santuarios aparecerán en unos segundos",
"Сервер мест не ответил":"El servidor de lugares no respondió",
"Посылка из Ордена":"Paquete de la Orden",
"Поблизости пока нет ни одного Источника, поэтому Орден раз в день присылает припасы: {0}.":"Aún no hay ninguna fuente cerca, así que la Orden te envía provisiones una vez al día: {0}.",
"Спасибо":"Gracias",
"На проверке":"En revisión",
"Одобрено":"Aprobado",
"Отклонено":"Rechazado",
"Места":"Lugares",
"Источники и Святилища стоят у настоящих мест. Знаешь интересный объект рядом? Предложи его!":"Las fuentes y los Santuarios están en lugares reales. ¿Conoces un sitio interesante cerca? ¡Propónlo!",
"<b>Подходят:</b> памятники, скульптуры, фонтаны, мозаики, необычные здания, храмы, парки, источники, смотровые площадки.":"<b>Sirven:</b> monumentos, esculturas, fuentes, mosaicos, edificios singulares, templos, parques, manantiales, miradores.",
"<b>Не подходят:</b> частные дома и дворы, школы и детские сады, опасные места (проезжая часть, стройки), обычные магазины.":"<b>No sirven:</b> casas y patios privados, escuelas y guarderías, lugares peligrosos (calzadas, obras), tiendas normales.",
"Стой рядом с объектом: снимок получает геометку, модератор сверяет её с точкой на карте.":"Quédate junto al lugar: la foto se geolocaliza y el moderador la compara con el punto del mapa.",
"Сфотографировать объект":"Fotografiar el lugar",
"Предлагать места можно с {0} уровня Ловчего.":"Puedes proponer lugares desde el nivel {0} de Cazador.",
"Не больше 5 заявок в сутки.":"No más de 5 propuestas al día.",
"Мои заявки":"Mis propuestas",
"Заявок пока нет.":"Aún no hay propuestas.",
"Нет связи с сервером: {0}":"Sin conexión con el servidor: {0}",
"Место «{0}» одобрено и появилось на карте! {1}":"¡El lugar «{0}» fue aprobado y ya está en el mapa! {1}",
"Место «{0}» отклонено: {1}":"El lugar «{0}» fue rechazado: {1}",
"Место «{0}» отклонено":"El lugar «{0}» fue rechazado",
"Камера недоступна на этом устройстве":"La cámara no está disponible en este dispositivo",
"Наведи камеру на объект целиком":"Encuadra el lugar completo con la cámara",
"Нет доступа к камере":"Sin acceso a la cámara",
"Место — где ты на карте":"Lugar: donde estás en el mapa",
"Камера ещё включается":"La cámara aún se está encendiendo",
"Сначала выбери место в Атласе мира":"Primero elige un lugar en el Atlas del mundo",
"Новое место":"Nuevo lugar",
"Название":"Nombre",
"Например: Памятник Пушкину":"Por ejemplo: Monumento a Pushkin",
"Чем интересно (необязательно)":"Qué tiene de interesante (opcional)",
