"Перепутица спутала дороги мира, и Орден Оберега открыл Ловчим Врата: выбери в Атласе мира любой уголок Земли — там и начнёшь охоту. По карте ходи джойстиком, а в новые края шагай через Атлас. Настоящее местоположение телефона игре не нужно. Прогресс хранится на сервере игры и доступен только тебе; сервер проверяет каждое действие, поэтому нужен интернет. Места на карте и погода загружаются для выбранного района у OpenStreetMap и Open-Meteo (погоду можно выключить в настройках).":"La Gran Maraña enredó los caminos del mundo, y la Orden del Talismán abrió las Puertas a los Cazadores: elige en el Atlas del mundo cualquier rincón de la Tierra; allí empezará tu caza. Muévete por el mapa con el joystick y viaja a nuevas tierras a través del Atlas. El juego no necesita la ubicación real de tu teléfono. Tu progreso se guarda en el servidor del juego y solo tú tienes acceso; el servidor comprueba cada acción, por eso hace falta internet. Los lugares del mapa y el clima de la zona elegida se cargan desde OpenStreetMap y Open-Meteo (el clima se puede desactivar en los ajustes).",
"Уже играешь?":"¿Ya juegas?",
