"Игра переехала на свой сервер в России — <b>duholov.ru</b>. Для этого вышло новое приложение: его нужно установить заново.":"El juego se mudó a su propio servidor en Rusia: <b>duholov.ru</b>. Para ello salió una nueva app, que hay que instalar de nuevo.",
"Привяжи вход: Меню → Настройки → Учётная запись (Google, Яндекс, VK, Telegram или почта). Без этого прогресс гостя не перенесётся.":"Vincula un inicio de sesión: Menú → Ajustes → Cuenta (Google, Yandex, VK, Telegram o correo). Sin esto, el progreso de invitado no se transferirá.",
